import React, { useEffect, useState } from "react";
import axios from "axios";

const Play = () => {
  const [games, setGames] = useState([]);
  const [selectedAge, setSelectedAge] = useState("3-5");

  useEffect(() => {
    axios
      .get("http://localhost:5001/api/games")
      .then((res) => setGames(res.data))
      .catch(() => {
        // временные данные, если backend не готов
        setGames([
          {
            id: 1,
            title: "Color the Animal",
            description: "Color cute animals and relax",
            age_group: "3-5",
            image_url: "/assets/images/games/color.png",
          },
          {
            id: 2,
            title: "Memory Cards",
            description: "Train your memory",
            age_group: "6-8",
            image_url: "/assets/images/games/memory.png",
          },
          {
            id: 3,
            title: "Math Challenge",
            description: "Solve fun math tasks",
            age_group: "9-12",
            image_url: "/assets/images/games/math.png",
          },
          {
            id: 4,
            title: "Relax & Breathe",
            description: "Calm down and breathe",
            age_group: "13+",
            image_url: "/assets/images/games/relax.png",
          },
        ]);
      });
  }, []);

  const filteredGames = games.filter(
    (game) => game.age_group === selectedAge
  );

  return (
    <main className="min-h-screen bg-slate-100 p-6">
      <h1 className="text-4xl font-bold text-center mb-2">
        Play & Have Fun 🎈
      </h1>
      <p className="text-center text-gray-600 mb-8">
        Choose a game made just for you!
      </p>

      {/* AGE FILTER */}
      <div className="flex justify-center gap-4 mb-10">
        {["3-5", "6-8", "9-12", "13+"].map((age) => (
          <button
            key={age}
            onClick={() => setSelectedAge(age)}
            className={`px-6 py-2 rounded-full font-semibold transition
              ${
                selectedAge === age
                  ? "bg-purple-500 text-white"
                  : "bg-white text-gray-700 hover:bg-purple-100"
              }`}
          >
            {age}
          </button>
        ))}
      </div>

      {/* GAMES */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {filteredGames.map((game) => (
          <div
            key={game.id}
            className="bg-white rounded-2xl shadow p-5 flex flex-col hover:scale-[1.02] transition"
          >
            <img
              src={game.image_url}
              alt={game.title}
              className="h-40 object-contain mb-4"
            />

            <h3 className="text-xl font-bold">{game.title}</h3>
            <p className="text-sm text-gray-600 mb-4">
              {game.description}
            </p>

            <button className="mt-auto bg-green-500 text-white py-2 rounded-xl font-semibold hover:bg-green-600">
              ▶ Play
            </button>
          </div>
        ))}
      </div>
    </main>
  );
};

export default Play;
